import java.time.*;import java.util.*;
public class Main { static class Vehicle{String no,type,user;Vehicle(String n,String t,String u){no=n;type=t;user=u;}} static class Ticket{long id;Vehicle v;LocalDateTime in;int floor,slot;Ticket(long i,Vehicle v,int f,int s){id=i;this.v=v;floor=f;slot=s;in=LocalDateTime.now();}} static class Parking{String[][] slots={new String[3],new String[4]};Map<String,Ticket> active=new HashMap<>();long seq=1000;Ticket enter(Vehicle v){if(active.containsKey(v.no))throw new IllegalArgumentException("Already parked");for(int f=0;f<slots.length;f++)for(int s=0;s<slots[f].length;s++)if(slots[f][s]==null){slots[f][s]=v.no;Ticket t=new Ticket(++seq,v,f,s);active.put(v.no,t);return t;}throw new IllegalStateException("Parking full");}double exit(String no,int minutes){Ticket t=active.remove(no);if(t==null)throw new IllegalArgumentException("No active ticket");slots[t.floor][t.slot]=null;if(!t.v.user.equals("VISITOR"))return 0;int h=(minutes+59)/60;return h*(t.v.type.equals("CAR")?30:15);} } public static void main(String[]a){Parking p=new Parking();Ticket t=p.enter(new Vehicle("TN01AB1234","CAR","VISITOR"));System.out.println("Ticket="+t.id+" floor="+t.floor+" slot="+t.slot);System.out.println("Fee=Rs."+p.exit("TN01AB1234",90));}}
